export function triggerEvent(s,type,x=null,y=null){if(!HAZARDS[type])return fail('Evento desconocido.');const m=currentMap(s),u=m.units.find(u=>alive(u)&&!u.embarked)||{x:m.size/2,y:m.size/2},radius=HAZARDS[type].radius,offset=(s.serial%3-1)*5,e={id:'event'+s.serial++,map:m.id,type,x:x??Math.floor(u.x)+offset,y:y??Math.floor(u.y)+5,starts:s.time+(has(m,'lab')?45:15),ends:s.time+75,radius,applied:false};if(['seaquake','tsunami'].includes(type)){const gate=m.exits[Math.floor(randomAt(s.serial,0,m.seed)*m.exits.length)];if(gate){e.x=gate.x;e.y=gate.y;}}s.events.push(e);log(s,'Alerta: '+HAZARDS[type].name+'. Revisa el área señalada.');return ok('Evento registrado.');}
